mapper.select:
SELECT id, project_id, station_id, instrument_id, metric_code, engineering_metric_code, observed_at,
       raw_value, raw_unit, metric_value, metric_unit, baseline_value,
       quality_flag, conversion_operator_code, conversion_version, conversion_status, conversion_remark,
       source_record_key, created_at
FROM ${tableName}

    AND project_id = #{query.projectId}
    AND station_id = #{query.stationId}

        AND station_id IN

            #{stationId}


    AND instrument_id = #{query.instrumentId}

        AND instrument_id IN

            #{instrumentId}



        AND (metric_code = #{query.metricCode} OR engineering_metric_code = #{query.metricCode})

    AND observed_at >= #{query.startTime}
    AND observed_at <= #{query.endTime}

ORDER BY observed_at DESC, id DESC
LIMIT #{limit}
